class AdvancedItem:
    def __init__(self, name, value, category):
        self._name = name
        self._value = value
        self._category = category

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        if not isinstance(value, str):
            raise TypeError("name must be a string")
        self._name = value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, value):
        if not isinstance(value, int):
            raise TypeError("value must be an integer")
        self._value = value

    @property
    def category(self):
        return self._category

    @category.setter
    def category(self, value):
        if not isinstance(value, str):
            raise TypeError("category must be a string")
        self._category = value

    def set_attributes(self, name, value, category):
        self._name = name
        self._value = value
        self._category = category

    def describe(self):
        return f"{self._name} belongs to {self._category} with value {self._value}"
