from itertools import zip_longest

def create_product_price_map(product_ids, prices):
    """
    Creates a dictionary mapping product IDs to their prices.
    Handles unequal list lengths by filling in None for missing values.

    Args:
        product_ids (list): List of product IDs (strings or integers)
        prices (list): List of product prices (numbers or None)

    Returns:
        dict: Dictionary mapping product IDs to prices
    """
    return dict(zip_longest(product_ids, prices, fillvalue=None))

def check_solution():
    """
    Test function to verify the correctness of create_product_price_map.
    """
    test_cases = [
        {
            "name": "Equal Length Lists",
            "product_ids": ["P001", "P002", "P003"],
            "prices": [10.99, 25.50, 15.00],
            "expected": {"P001": 10.99, "P002": 25.50, "P003": 15.00}
        },
        {
            "name": "IDs Longer Than Prices",
            "product_ids": ["P001", "P002", "P003", "P004"],
            "prices": [10.99, 25.50],
            "expected": {"P001": 10.99, "P002": 25.50, "P003": None, "P004": None}
        },
        {
            "name": "Prices Longer Than IDs",
            "product_ids": ["P001", "P002"],
            "prices": [10.99, 25.50, 15.00],
            "expected": {"P001": 10.99, "P002": 25.50}
        },
        {
            "name": "Empty Lists",
            "product_ids": [],
            "prices": [],
            "expected": {}
        },
        {
            "name": "Mixed None Values",
            "product_ids": ["P001", "P002", "P003"],
            "prices": [10.99, None, 15.00],
            "expected": {"P001": 10.99, "P002": None, "P003": 15.00}
        },
        {
            "name": "Integer IDs",
            "product_ids": [1, 2, 3],
            "prices": [100, 200, 300],
            "expected": {1: 100, 2: 200, 3: 300}
        }
    ]

    all_passed = True
    for i, test in enumerate(test_cases, 1):
        result = create_product_price_map(test["product_ids"], test["prices"])
        passed = result == test["expected"]
        status = "✓ PASS" if passed else "✗ FAIL"
        print(f"Test {i}: {test['name']} - {status}")
        if not passed:
            print(f"  Expected: {test['expected']}")
            print(f"  Got:      {result}")
            all_passed = False

    print("\n" + "=" * 50)
    if all_passed:
        print("All tests passed successfully!")
    else:
        print("Some tests failed. Please review the output above.")
    print("=" * 50)

if __name__ == "__main__":
    check_solution()

