class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError("Pop from empty stack")
        return self.items.pop()

    def peek(self):
        if self.is_empty():
            raise IndexError("Peek from empty stack")
        return self.items[-1]

    def is_empty(self):
        return len(self.items) == 0

    def size(self):
        return len(self.items)

    def __str__(self):
        return f"Stack({self.items})"

class PostfixEvaluator:
    def __init__(self):
        self.operators = {'+', '-', '*', '/', '%', '^'}
        self.precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '%': 2, '^': 3}

    def is_operator(self, char):
        return char in self.operators

    def is_number(self, char):
        return char.isdigit() or char == '.'

    def evaluate(self, expression):
        stack = Stack()
        i = 0

        while i < len(expression):
            char = expression[i]

            if char.isspace():
                i += 1
                continue

            if self.is_number(char):
                # Handle multi-digit numbers
                num = char
                while i + 1 < len(expression) and expression[i + 1].isdigit():
                    num += expression[i + 1]
                    i += 1
                stack.push(num)
            elif self.is_operator(char):
                if stack.size() < 2:
                    raise ValueError(f"Invalid expression: {expression}")

                op2 = stack.pop()
                op1 = stack.pop()

                if isinstance(op1, str) and isinstance(op2, str):
                    raise ValueError(f"Invalid expression: {expression}")

                result = self.apply_operator(op1, op2, char)
                stack.push(result)
            else:
                raise ValueError(f"Invalid character: {char}")

            i += 1

        if stack.size() != 1:
            raise ValueError(f"Invalid expression: {expression}")

        return stack.pop()

    def apply_operator(self, op1, op2, operator):
        if operator == '+':
            return op1 + op2
        elif operator == '-':
            return op1 - op2
        elif operator == '*':
            return op1 * op2
        elif operator == '/':
            if op2 == 0:
                raise ZeroDivisionError("Division by zero")
            return op1 / op2
        elif operator == '%':
            if op2 == 0:
                raise ZeroDivisionError("Modulo by zero")
            return op1 % op2
        elif operator == '^':
            return op1 ** op2
        else:
            raise ValueError(f"Unknown operator: {operator}")

def compress_rle(data: str) -> str:
    """
    Compresses a string using Run-Length Encoding.
    Each sequence of identical characters is replaced by the count followed by the character.
    """
    if not data:
        return ""

    result = []
    count = 1

    for i in range(1, len(data) + 1):
        if i == len(data) or data[i] != data[i - 1]:
            result.append(str(count) + data[i - 1])
            count = 1
        else:
            count += 1

    return "".join(result)


