def add_sparse_matrices(mat1, mat2):
    """
    Adds two sparse matrices represented as dictionaries of dictionaries.

    Args:
        mat1 (dict): First sparse matrix, where mat1[row][col] = value
        mat2 (dict): Second sparse matrix, where mat2[row][col] = value

    Returns:
        dict: Resulting sparse matrix with non-zero values only
    """
    # Get all unique rows from both matrices
    all_rows = set(mat1.keys()) | set(mat2.keys())

    result = {}

    for row in all_rows:
        cols1 = mat1.get(row, {})
        cols2 = mat2.get(row, {})

        # Get all unique columns for this row
        all_cols = set(cols1.keys()) | set(cols2.keys())

        # Create the row dictionary
        row_dict = {}
        for col in all_cols:
            val1 = cols1.get(col, 0)
            val2 = cols2.get(col, 0)
            total = val1 + val2

            # Only include non-zero values
            if total != 0:
                row_dict[col] = total

        # Only include rows that have at least one non-zero value
        if row_dict:
            result[row] = row_dict

    return result

