def solve():
    # Read all input from standard input
    # split() handles newlines and spaces automatically
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        # Read the number of spells
        N = int(next(iterator))

        # Read the power levels of the spells
        spells = []
        for _ in range(N):
            spells.append(int(next(iterator)))

        # Read the maximum power limit
        M = int(next(iterator))
    except StopIteration:
        return

    max_power = -1
    found = False

    # Iterate through all possible non-empty combinations of spells.
    # Since N is small (up to 10), checking all 2^N - 1 subsets is efficient.
    # We use combinations to generate subsets of size r from 1 to N.
    for r in range(1, N + 1):
        for combo in combinations(spells, r):
            current_sum = sum(combo)

            # Check if the current combination is within the power limit
            if current_sum <= M:
                if current_sum > max_power:
                    max_power = current_sum
                found = True

    # Output the result
    if found:
        print(max_power)
    else:
        print("No valid spell")

