import bisect

def longest_progressive_subsequence(ages: List[int]) -> int:
    """Find the length of the longest progressive subsequence within a list of ages.
    >>> longest_progressive_subsequence([5, 3, 4, 8, 6, 7, 9])
    5
    >>> longest_progressive_subsequence([1, 3, 2, 4, 6])
    4
    """
    if not ages:
        return 0

    tails = []  # tails[i] = smallest tail of all increasing subsequences of length i+1

    for age in ages:
        pos = bisect.bisect_left(tails, age)
        if pos == len(tails):
            tails.append(age)
        else:
            tails[pos] = age

    return len(tails)

