import sys

def solve():
    # Read all input from standard input
    # split() handles newlines and spaces, returning a list of tokens
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        # The first two tokens are the dimensions n and m
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    # Read the grid rows
    # Based on the problem description and examples, each row is a string of '0's and '1's
    grid = []
    for _ in range(n):
        try:
            row_str = next(iterator)
            grid.append(row_str)
        except StopIteration:
            break

    # dp[i][j] will store the side length of the largest square of '1's
    # whose bottom-right corner is at (i, j)
    # Initialize with zeros
    dp = [[0] * m for _ in range(n)]
    max_side = 0

    # Iterate through each cell of the grid
    for i in range(n):
        for j in range(m):
            # Check if the current cell is suitable for cultivation ('1')
            if grid[i][j] == '1':
                # If it's the first row or first column, the largest square ending here is 1x1
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    # Otherwise, the side length is determined by the minimum of the
                    # three adjacent squares (top, left, top-left) plus 1
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1

                # Update the maximum side length found so far
                if dp[i][j] > max_side:
                    max_side = dp[i][j]
            else:
                # If the cell is '0', no square can end here
                dp[i][j] = 0

    # Print the result to stdout
    print(max_side)

if __name__ == '__main__':
    solve()

def hex_string_analysis(hex_string):
    """
    Analyzes a hexadecimal string and returns:
    - Number of hexadecimal digits
    - Sum of the decimal values of each digit

    Args:
        hex_string (str): A string representing a hexadecimal number.
                          May include an optional '0x' or '0X' prefix.

    Returns:
        tuple: (num_digits, hex_sum)

    Raises:
        ValueError: If the string contains invalid hexadecimal characters.
    """
    hex_string = hex_string.strip()

    if not hex_string:
        return (0, 0)

    # Remove optional '0x' or '0X' prefix
    if hex_string.lower().startswith('0x'):
        hex_string = hex_string[2:]

    if not hex_string:
        return (0, 0)

    num_digits = len(hex_string)
    hex_sum = 0

    for char in hex_string:
        if char in '0123456789':
            hex_sum += int(char, 16)
        elif char in 'abcdefABCDEF':
            hex_sum += int(char.upper(), 16)
        else:
            raise ValueError(f"Invalid hexadecimal character: {char}")

    return (num_digits, hex_sum)

