def is_hamiltonian_cycle(n: int, edges: List[Tuple[int, int]]) -> str:
    """
    Check if it is possible to create a sequence such that every student can pass the baton exactly once to one of their friends.
    """
    if n == 0:
        return "impossible"

    # Build adjacency list
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # If no edges and n > 0, impossible
    if len(edges) == 0:
        return "impossible"

    # For n = 2, need at least 1 edge
    if n == 2 and len(edges) < 1:
        return "impossible"

    # Check if all vertices 1..n are present in the graph
    for i in range(1, n + 1):
        if i not in adj:
            return "impossible"

    # For n > 2, each vertex must have degree at least 2
    if n > 2:
        for i in range(1, n + 1):
            if len(adj[i]) < 2:
                return "impossible"

    # Check if graph is connected
    visited = set()
    stack = [1]
    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            for neighbor in adj[node]:
                if neighbor not in visited:
                    stack.append(neighbor)

    if len(visited) != n:
        return "impossible"

    # Try to find Hamiltonian cycle using DFS
    def dfs(current, visited, path):
        if len(path) == n:
            return 1 in adj[current]

        for neighbor in adj[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                path.append(neighbor)
                if dfs(neighbor, visited, path):
                    return True
                path.pop()
                visited.remove(neighbor)

        return False

    visited = set()
    visited.add(1)
    path = [1]

    if dfs(1, visited, path):
        return "possible"
    else:
        return "impossible"


