from collections import deque

def find_shortest_path(matrix, source, target):
    rows, cols = len(matrix), len(matrix[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Validate source and target
    if not (0 <= source[0] < rows and 0 <= source[1] < cols):
        return []
    if not (0 <= target[0] < rows and 0 <= target[1] < cols):
        return []
    if source == target:
        return [source]

    # BFS initialization
    queue = deque([(source, [source])])  # (current_position, path)
    visited = {source}

    while queue:
        (r, c), path = queue.popleft()

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and matrix[nr][nc] != 1 and (nr, nc) not in visited:
                visited.add((nr, nc))
                new_path = path + [(nr, nc)]
                if (nr, nc) == target:
                    return new_path
                queue.append(((nr, nc), new_path))

    return []  # No path found

