def calculate_calories_burned(activities):
    """
    Calculate total calories burned based on activity types, durations, and intensities.

    Args:
        activities (list of tuples): Each tuple contains (activity_type, duration, intensity)

    Returns:
        int: Total calories burned
    """
    calorie_rates = {
        "walking": {"low": 3, "medium": 4.5, "high": 6},
        "running": {"low": 8, "medium": 11, "high": 14},
        "cycling": {"low": 5, "medium": 7.5, "high": 10}
    }

    total_calories = 0

    for activity_type, duration, intensity in activities:
        if activity_type not in calorie_rates:
            raise ValueError(f"Unknown activity type: {activity_type}")
        if intensity not in calorie_rates[activity_type]:
            raise ValueError(f"Invalid intensity for {activity_type}: {intensity}")
        rate = calorie_rates[activity_type][intensity]
        total_calories += duration * rate

    return int(total_calories)

