def schedule_tasks(tasks: Dict[TaskID, TaskDict]) -> Dict[TaskID, bool]:
    """
    Schedule and execute tasks based on priority.

    Args:
        tasks: Dictionary mapping TaskID to TaskDict

    Returns:
        Dictionary mapping TaskID to execution results (bool)
    """
    # Sort tasks by priority (highest first)
    sorted_tasks = sorted(
        tasks.items(),
        key=lambda item: item[1]['priority'],
        reverse=True
    )

    # Dictionary to store execution results
    results: Dict[TaskID, bool] = {}

    # Execute tasks in priority order
    for task_id, task in sorted_tasks:
        results[task_id] = task['execute']()

    return results

