from typing import List

def lexicographically_smallest_subgrid(grid: List[str]) -> str:
    """
    Find the lexicographically smallest string formed by any subgrid.
    A subgrid is any rectangular region of the grid.
    For each subgrid, we form a string by concatenating its characters in row-major order.
    We return the lexicographically smallest such string.
    """
    if not grid or not grid[0]:
        return ""

    rows = len(grid)
    cols = len(grid[0])

    min_str = None

    for r1 in range(rows):
        for c1 in range(cols):
            for r2 in range(r1, rows):
                for c2 in range(c1, cols):
                    # Extract subgrid
                    subgrid_chars = []
                    for r in range(r1, r2 + 1):
                        for c in range(c1, c2 + 1):
                            subgrid_chars.append(grid[r][c])
                    subgrid_str = "".join(subgrid_chars)

                    if min_str is None or subgrid_str < min_str:
                        min_str = subgrid_str

    return min_str

