def portfolio_evaluation(stock_quantities: dict, stock_prices: dict, percentage_changes: dict) -> dict:
    """
    Evaluates the performance of a stock portfolio.

    Parameters:
    stock_quantities (dict): Dictionary of stock tickers and quantities held.
    stock_prices (dict): Dictionary of stock tickers and current stock prices.
    percentage_changes (dict): Dictionary of stock tickers and percentage change in stock prices.

    Returns:
    dict: Dictionary containing total value, individual stock values, and percentage changes.

    Example:
    >>> stock_quantities = {"AAPL": 10, "TSLA": 5, "GOOGL": 2}
    >>> stock_prices = {"AAPL": 150.0, "TSLA": 720.5, "GOOGL": 2800.0}
    >>> percentage_changes = {"AAPL": 5.0, "TSLA": -2.0, "GOOGL": 1.2}
    >>> portfolio_evaluation(stock_quantities, stock_prices, percentage_changes)
    {
        'total_value': 15920.0,
        'individual_values': {"AAPL": 1500.0, "TSLA": 3602.5, "GOOGL": 5600.0},
        'percentage_changes': {"AAPL": 5.0, "TSLA": -2.0, "GOOGL": 1.2}
    }
    """
    individual_values = {}
    total_value = 0.0

    for ticker, quantity in stock_quantities.items():
        if ticker in stock_prices:
            price = stock_prices[ticker]
            value = quantity * price
            individual_values[ticker] = value
            total_value += value

    return {
        'total_value': total_value,
        'individual_values': individual_values,
        'percentage_changes': percentage_changes
    }

def multiply_sparse_matrices(A, B):
    """
    Multiplies two sparse matrices A (m x n) and B (n x l) efficiently
    by focusing only on non-zero elements.

    :type A: List[List[int]]
    :type B: List[List[int]]
    :rtype: List[List[int]]
    """
    if not A or not B:
        return []

    m = len(A)
    n = len(A[0])
    l = len(B[0])

    # Convert A to row dictionaries: {row_index: {col_index: value}}
    A_dict = {}
    for i in range(m):
        A_dict[i] = {}
        for j in range(n):
            if A[i][j] != 0:
                A_dict[i][j] = A[i][j]

    # Convert B to column dictionaries: {col_index: {row_index: value}}
    B_col = {}
    for j in range(l):
        B_col[j] = {}
        for i in range(n):
            if B[i][j] != 0:
                B_col[j][i] = B[i][j]

    # Initialize result matrix
    result = [[0] * l for _ in range(m)]

    # Compute matrix multiplication using non-zero elements only
    for i in range(m):
        for j in range(l):
            if i in A_dict and j in B_col:
                row_a = A_dict[i]
                col_b = B_col[j]
                for k in range(n):
                    if k in row_a and k in col_b:
                        result[i][j] += row_a[k] * col_b[k]

    return result

