import heapq

class PriorityQueue:
    def __init__(self, items=None, priorities=None):
        self.priority_queue_list = []
        if items is not None and priorities is not None:
            for item, priority in zip(items, priorities):
                self.push(item, priority)
        elif items is not None:
            for item in items:
                self.push(item)

    def size(self) -> int:
        return len(self.priority_queue_list)

    def push(self, item: int, priority: int = None) -> None:
        if priority is None:
            priority = item
        heapq.heappush(self.priority_queue_list, (priority, item))

    def pop(self) -> int:
        if not self.priority_queue_list:
            raise IndexError("pop from empty queue")
        _, item = heapq.heappop(self.priority_queue_list)
        return item

