from typing import List, Tuple
from collections import defaultdict, deque

def is_network_connected(connections: List[Tuple[str, str]]) -> bool:
    """
    Analyze a given network of computers and identify whether there exists at least one path 
    connecting every pair of computers directly or indirectly.
    """
    if not connections:
        return False

    graph = defaultdict(list)
    nodes = set()

    for u, v in connections:
        graph[u].append(v)
        graph[v].append(u)
        nodes.add(u)
        nodes.add(v)

    if not nodes:
        return False

    visited = set()
    start_node = next(iter(nodes))
    queue = deque([start_node])
    visited.add(start_node)

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return len(visited) == len(nodes)

