def decimal_to_binary(n):
    """
    Convert a decimal integer to its binary string representation
    using only bitwise operations.
    """
    if n == 0:
        return '0'

    binary = ''
    while n != 0:
        # Check if the least significant bit is 1
        if n & 1:
            binary = '1' + binary
        else:
            binary = '0' + binary
        # Right shift to process the next bit
        n >>= 1

    return binary

def decimal_to_binary_with_sign(n):
    """
    Convert a decimal integer to its binary string representation
    with a sign prefix for negative numbers.
    """
    if n == 0:
        return '0'

    binary = ''
    while n != 0:
        if n & 1:
            binary = '1' + binary
        else:
            binary = '0' + binary
        n >>= 1

    if n < 0:
        return '-' + binary
    else:
        return binary

